  "followups.content.0": "¡Suelta el ritmo y muévete!",
  "followups.content.1": "¡Tiempo de Remix!",
  "followups.content.2": "Mi pista... saltó...",
  "followups.content.3": "¡Sorpresa!",
  "followups.content.4": "Váyame, ¡te derribaré!",
  "followups.content.5": "Sprung... y hecho...",
  "followups.content.6": "¡Dispara al intruso!",
  "followups.content.7": "¡La tormenta es mía!",
  "followups.content.8": "Abandona... nave...",
  "followups.content.9": "¡En garde!",
  "followups.content.10": "Afeitado con cada paso.",
  "followups.content.11": "Sólo un rasguño... creo.",
  "followups.content.12": "Corte limpio.",
  "followups.content.13": "Un oponente digno.",
  "followups.content.14": "¡Vuelve al duelo!",
  "followups.content.15": "Mi espada evoluciona.",
  "followups.content.16": "Victoria, con estilo.",
  "followups.content.17": "¡Robando el fuego!",
  "followups.content.18": "¡Hotter y más caliente!",
  "followups.content.19": "¡Mi llama está parpadeando!",
  "followups.content.20": "¡Quemado a un crujiente!",
  "followups.content.21": "Gran jefe, fuego más grande.",
  "followups.content.22": "¡El horno ruge otra vez!",
  "followups.content.23": "¡Blaze completo!",
  "followups.content.24": "No queda más que cenizas.",
  "followups.content.25": "¡Dos de nosotros, dos veces el problema!",
  "followups.content.26": "¡Hemos nivelado juntos!",
  "followups.content.27": "Hey, estamos lastimando aquí!",
  "followups.content.28": "Tenemos esto, ¿verdad?",
  "followups.content.29": "¡Alta cinco, yo!",
  "followups.content.30": "El camino comienza.",
  "followups.content.31": "Mi espada crece más afilada.",
  "followups.content.32": "Estoy herido... no golpeado.",
  "followups.content.33": "Un corte, un asesinato.",
  "followups.content.34": "Enfrentame, gigante.",
  "followups.content.35": "Me levanto de nuevo.",
  "followups.content.36": "La espada despierta.",
  "followups.content.37": "El duelo está hecho.",
  "followups.content.38": "¡Construyamos un ejército!",
  "followups.content.39": "¡Ooh, nuevas partes!",
  "followups.content.40": "¡Necesito reparaciones!",
  "followups.content.41": "¡Mis bots hicieron eso!",
  "followups.content.42": "¡Gran jefe, robots más grandes!",
  "followups.content.43": "¡Reiniciado y listo!",
  "followups.content.44": "¡Completa de actualización!",
  "followups.content.45": "Tinkering paga!",
