  "secrets.wall": "RELÉ CRACKED\nApunta y dispara a la grieta brillante.",
  "secrets.plates": "SECRET · PLACAS DE PRESIÓN\nPaso a 1 → 2 → 3: izquierda, derecha, media.",
  "secrets.runes": "SECRET · GOLPEAR A LOS CORREDORES\nDispara a la izquierda, a la derecha, en medio de un chime.\nLos cubos de oro marcan el ritmo, incluso cuando se mutilan.",
  "secrets.braziers": "SECRET · TRES BRAZIERS\nLas armas de fuego encienden a los braseros.\n¿No hay fuego? Ponte en la almohadilla de oro, luego apunta y dispara.",
  "secrets.ice": "SECRET · CRUCE CONGELADO\nCongelar el cristal azul, luego cruzar el agua.\nCarga en la almohadilla de oro, luego dispara.",
  "secrets.done": "RELÉ RESTAURADO · RELIC AWARDED\nVisita la terminal verde, el robot conoce un baile.",
