  "secrets.skin": "Armadura del repetidor píxel",
  "secrets.skin_short": "Pixel Relay",
  "secrets.skin_condition": "Resolver una habitación secreta o descubrir el antiguo código direccional.",
  "secrets.category": "SECRETO",
  "secrets.lore_name": "El relé olvidado",
  "secrets.developer_name": "El turno de la noche",
  "secrets.lore": "El equipo de mantenimiento escondió un taller detrás de una pared falsa. Tres lámparas recuerdan el orden: izquierda, derecha, media. Cada relé resuelto todavía envía un agradecimiento.",
  "secrets.developer_lore": "Una pequeña habitación para todos los que mantuvieron las islas corriendo. El robot baila porque alguien finalmente regresó. Gracias por jugar.",
  "secrets.king_lore": "SECRET: Tres Goldbugs desaparecidos despertaron a su rey. Su corona recuerda cada moneda robada. Mira los anillos de aterrizaje dorados. Sigue moviéndose y observa su viento.",
  "secrets.shadow_lore": "SECRET: Una noche impecable deja atrás un reflejo. Ciclo a través de tus patrones de armas; su poder prestado tiene límites seguros. Sigue moviendo y vigilando su viento.",
  "secrets.a_room": "Fuera del mapa",
  "secrets.a_room_desc": "Resolver una sala secreta de relés.",
  "secrets.a_king": "Real Auditoría Real",
  "secrets.a_king_desc": "SECRET: capturar tres Goldbugs en una sola carrera, despertar la estatua de oro, y derrotar al Rey Dorado.",
  "secrets.a_shadow": "Mejor que mi sombra",
  "secrets.a_shadow_desc": "SECRET: derrota tu reflexión después de una etapa nocturna impecable.",
  "secrets.a_code": "Escuela vieja",
  "secrets.a_code_desc": "Descubra el antiguo código direccional en la pantalla del título.",
