  "content.84fee1b908": "Explosiones de viento cruzado",
  "content.21f48f0714": "Las cuchillas pardas de crescent cruzan hacia fuera, luego rebanan a lo largo de un camino de retorno curvado.",
  "content.bceb0fd05d": "Bobinas Tesla",
  "content.20e9db560e": "Tira las bobinas detrás de usted. Desplazan enemigos cercanos y electrifican la línea a la bobina anterior.",
  "content.3fa4624af4": "Enjambre de misiles",
  "content.d5a30861d8": "Los aficionados pequeños misiles de homenaje en una onda estancada.",
  "content.33308c454a": "Fragmentos de prisma",
  "content.7b8ce4b3a3": "Cristales ricochet entre enemigos. Cada uno se divide en dos cristales más pequeños en su primer golpe.",
  "content.6ae4da1570": "Látigo de luz",
  "content.dda58a2099": "Barre un haz flexible a través de un arco ancho. Cada swing golpea a un enemigo una vez.",
  "content.d20d4a8f64": "Torreta de bolsillo",
  "content.5191e9018c": "CLICK DERECHO: desplegar un centinela en el cursor. Rastrea y dispara a los enemigos; colocar otro reemplaza al más antiguo.",
  "content.b2ecb120df": "Glass Gale",
  "content.1519201745": "FUSION of Crosswind Blades + Prism Shards. Las cuchillas Crescent irrumpen en los flashes de cristal mientras se dividen los fragmentos rebotados a través de la multitud.",
  "content.1ded80863d": "Hornet Grid",
  "content.5085777882": "FUSION of Tesla Coils + Swarm Misiles. Una batería de misiles eléctricos: las explosiones micromisiles saltan relámpagos a través de enemigos cercanos mientras las bobinas protegen su rastro.",
  "content.7bd71968dd": "Riposte Cell",
  "content.f9fa5592c1": "Torbellino",
  "content.b3b5901935": "Encore",
  "content.55bf66186a": "Capacitor de efectivo",
  "content.718a53f70a": "Segunda mano",
