  "content.b9fe1a7ba3": "Jack en la caja",
  "content.907ba6a6a3": "Hearth",
  "content.f83f00dc6d": "Wallflower",
  "content.d8eb186561": "Cold Front",
  "content.aad40fcb8f": "Blood Primer",
  "content.6d90bab333": "La última palabra",
  "content.9b782f6760": "Flare de la señal",
  "content.8006dda1a1": "Pit Crew",
  "content.c834d3facb": "Contracoro",
  "content.a1471f3244": "Bond de sangre",
  "content.b725c5e5fe": "Wing Guard",
  "content.dd10e5feed": "Ovación permanente",
  "content.1b913d3b3f": "Suda un haz flexible a través de un arco ancho. Cada swing golpea a un enemigo una vez.",
  "content.a0fe8c20b1": "Deplora un centinela en el cursor. Rastrea y dispara a los enemigos; colocando otro reemplaza al más antiguo.",
  "content.672418ed7d": "Parry: golpes ganar +⟪0⟫ daño para ⟪1⟫s. Poner antes multiplicadores.",
  "content.9ec4a01350": "Perfect dash: Los golpes de Orbit y Trail cuestan +⟪0⟫% de daño por ⟪1⟫s.",
  "content.f6d86f700c": "Utilice su máximo: +⟪0⟫% de daño para ⟪1⟫s.",
  "content.3347d5257c": "Efectivo en un combo: los golpes ganan +⟪0⟫ daños por ⟪1⟫s. No hay prima de oro.",
  "content.73023179eb": "Después de un rebobinado termina: +⟪0⟫% de daño para ⟪1⟫s.",
  "content.9f02fc66b3": "Sobrevive al salir del meca: +⟪0⟫% de daño durante ⟪1⟫s, incluida la explosión de expulsión.",
  "content.c21d055973": "Abra un pecho: un ⟪0⟫m Shock nova tiene ⟪1⟫ daños.",
  "content.4796d804bf": "Dentro del fuego de tus Botas llameantes: los golpes de Fuego y Rastro infligen +⟪0⟫% de daño.",
  "content.1c57742cae": "Dentro de ⟪0⟫m de cobertura: Orbit y Area golpea el contrato +⟪1⟫% de daño.",
  "content.b1bbcf2021": "A ⟪0⟫m o más: los golpes de Escarcha y Cadena infligen +⟪1⟫% de daño.",
  "content.a58a60981e": "Cada golpe +⟪0⟫ daño. Max vida x⟪1⟫. Poner antes multiplicadores.",
  "content.5e37395e25": "Cada golpe pierde ⟪0⟫ daños, luego x⟪1⟫. Ganan fuertes éxitos; el orden importa.",
  "content.352a455638": "Tus Quemaduras dan a los aliados +⟪0⟫% de probabilidad de crítico contra ese enemigo (máximo del equipo +⟪1⟫%).",
  "content.0836247367": "Otros aliados dentro de ⟪0⟫m recargar todas las armas ⟪1⟫% más rápido (capítulo de equipo +⟪2⟫% velocidad).",
  "content.e76459c2b5": "Un aliado desvía a menos de ⟪0⟫m: emites una nova de Descarga de ⟪1⟫m que inflige ⟪2⟫ de daño. Recarga: ⟪3⟫s.",
  "content.87006ad396": "Comparte el ⟪0⟫% de la vida que recuperes realmente al matar con cada aliado a menos de ⟪1⟫m (máximo ⟪2⟫%).",
  "content.5cb95a9e84": "Un aliado hace una esquiva perfecta a menos de ⟪0⟫m: ganas ⟪1⟫s de invulnerabilidad (máximo ⟪2⟫s). Recarga: ⟪3⟫s.",
  "content.07d6955765": "Un aliado utiliza un máximo dentro de ⟪0⟫m: sus éxitos tratan +⟪1⟫% de daño para ⟪2⟫s.",
  "content.7042a34e52": "Gale Reapers",
  "content.4147d8d8ce": "Seis grandes crescents golpearon de nuevo a su regreso.",
  "content.17445c9856": "HOJAS DE VIENTO MÁXIMO + PROPULSORES DE CHORRO",
  "content.e8a4b67f4f": "Thunder Grid",
  "content.3c22ee344d": "Seis bobinas de largo alcance tejen una cerca de relámpago rápido.",
  "content.7c2b3d0cd9": "MAX TESLA BOBINAS + PAQUETE DE BATERÍA",
  "content.0551ec041f": "Armada de avispones",
  "content.ef5520301e": "Catorce avispas veloces y guiadas salen en una oleada continua.",
  "content.7254961088": "MÁX MISILES ENJAMBRE + CÉLULA DE ENERGÍA",
  "content.c00761a1fb": "Kaleidoscopio",
  "content.713510f70b": "Cuatro cristales ricochet seis veces y se dividieron en pequeños fragmentos.",
  "content.3f02a91752": "MAX PRISM SHARDS + RONDAS DE CRIO",
  "content.7eec71fe00": "Sunlash",
  "content.173f69c5f1": "Un látigo ardiendo (Fire), +40 grados y un 25% de daño.",
  "content.74236350d1": "EVOLUCIÓN DEL LÁTIGO DE BEAM",
  "content.bee03eb48f": "Twinlash",
  "content.c3d026a983": "Un segundo látigo va detrás de ti, ambos enemigos Shock.",
  "content.8847d2f7b5": "Glaciar",
  "content.c1de1b50b7": "Los pernos anchos de Frost perforan 2 foes. +20% daño.",
  "content.c2234f7ae0": "EVOLUCIÓN CENTINELA DE BOLSILLO",
