  "text.status_5f241c": "SITUACIÓN",
  "text.fire_hits_set_enemies_alight_damage_over_3_secon_4b5c8c": "Los golpes de fuego ponen enemigos a la luz: daño durante 3 segundos.",
  "text.shock_6d94cc": "Descarga",
  "text.shock_hits_make_an_enemy_take_20_damage_for_2_se_1b0221": "Los golpes de choque hacen que un enemigo tome +20% daño durante 2 segundos.",
  "text.freeze_654670": "Congelación",
  "text.frost_can_freeze_enemies_in_place_frozen_enemies_235019": "Frost puede congelar enemigos en su lugar. Los enemigos congelados dejan de moverse y atacar.",
  "text.exposed_a54eec": "Expuesto",
  "text.right_click_status_27d54e": "ESTADO DEL CLIC DERECHO",
  "text.every_right_click_hit_exposes_the_enemy_30_damag_d8136a": "Cada golpe de clic derecho expone al enemigo: +30% daño de todos durante 4 segundos.",
  "text.overload_9f476f": "Sobrecarga",
  "text.combo_burn_shock_4d6d6f": "COMBO: QUEMADURA + SHOCK",
  "text.burn_and_shock_on_the_same_enemy_explode_in_an_o_a57fb9": "Quema y golpe en el mismo enemigo explotar en una explosión de sobrecarga que crece con su nivel.",
  "text.shatter_6e8e3e": "Ruptura",
  "text.combo_kill_a_frozen_enemy_5ee0fa": "COMBO: MATAR A UN ENEMIGO CONGELADO",
  "text.a_frozen_enemy_that_dies_bursts_into_ice_shards__a04a90": "Un enemigo congelado que muere se mete en hielo que golpea todo lo que hay cerca.",
  "text.napalm_ac4b31": "Napalm",
  "text.combo_blast_a_burning_enemy_bd5453": "COMBO: ARRUINAR UN ENEMIGO ARDIENTE",
  "text.an_explosion_that_catches_a_burning_enemy_spread_2f28fe": "Una explosión que atrapa a un enemigo ardiente esparce fuego a todo en la explosión.",
  "text.item_max_lv_456b18": "OBJETO · NV MÁX. ⟪0⟫",
  "text.co_op_item_d47243": "OBJETO COOPERATIVO",
  "text.mod_c5a28f": "MOD",
  "text.mod_copies_the_next_slot_27924c": "MOD · COPIA LA SIGUIENTE RANURA",
  "text.cursed_mod_146292": "MOD MALDITO",
  "text.relic_62a15e": "RELIQUIA",
  "text.evolution_57341e": "EVOLUCIÓN ⟪0⟫",
  "text.max_a05aea": "MAX ⟪0⟫ + ⟪1⟫",
  "text.follow_the_moving_dirt_mound_only_explosions_rea_d78566": "Siga el montículo de suciedad en movimiento. Sólo las explosiones llegan a la clandestinidad. Salga del anillo rojo, luego castigarlo por encima del suelo.",
  "text.an_armoured_dirt_digger_explosions_still_reach_i_24d97e": "Un Dirt Digger blindado. Las explosiones todavía lo alcanzan bajo tierra; esperar fuera del anillo por su ventana de castigo.",
  "text.an_armoured_mirror_bot_with_the_same_readable_sc_a10396": "Un Espejo blindado Bot con el mismo escaneo legible. Rompe su ataque de copia para reclamar las monedas de bonificación.",
  "text.a_big_digger_with_a_wider_eruption_its_longer_ri_f0ce60": "Un gran excavador con una erupción más amplia. Su advertencia de anillo más larga le da tiempo para moverse; los explosivos golpean a través de la suciedad.",
  "text.scans_your_left_click_weapon_then_copies_a_weake_09264c": "Analiza tu arma con el botón izquierdo, luego copia una versión púrpura más débil. Mátalo mientras copias para monedas de bonificación.",
  "text.copies_for_longer_and_keeps_farther_away_the_sca_eea86f": "Copies for longer and kept farther away. The scan line locks before its attack; move sideways.",
  "text.screeches_before_a_wall_of_swarmers_splits_the_a_5886e0": "Tornillos antes de que una pared de enjambres divida la arena. Corta una brecha, rompe los huevos verdes antes de que eclosionen, y persigue su retiro.",
  "text.a_fragile_cluster_that_hatches_four_swarmers_aft_adbb89": "Un cúmulo frágil que azota a cuatro enanos después de seis segundos. ¡Destruye primero!",
  "text.holds_the_queen_s_wall_for_twelve_seconds_then_j_2f703d": "Sostiene la pared de la Reina durante doce segundos, luego se une a la persecución. Dispara una brecha a través de la línea.",
  "text.comes_in_clouds_and_rings_keep_moving_and_let_ar_696216": "Viene en nubes y anillos. Siga moviendo y deje que las armas del área hagan el trabajo.",
  "text.flashes_red_then_lunges_sidestep_the_lunge_and_i_ff7780": "Relámpagos rojos, luego pulmones. Pase el pulmón y está abierto.",
  "text.fast_and_fragile_pierce_and_chain_weapons_clean__db8a3b": "Rápido y frágil. Pierce y las armas de cadena limpian paquetes.",
  "text.keeps_its_distance_and_fires_a_fan_strafe_across_fcd7c5": "Mantiene su distancia y dispara a un fan. Atravesa el ventilador, no lejos de ella.",
  "text.spins_out_a_double_spiral_walk_with_the_gaps_as__21410b": "Gire hacia fuera una doble espiral. Camine con los huecos mientras giran.",
  "text.three_quick_fans_in_a_row_dash_through_after_the_d70eb7": "Tres ventiladores rápidos seguidos.",
  "text.its_red_line_shows_the_shot_step_off_the_line_be_b5eac6": "Su línea roja muestra el disparo. Salga de la línea antes de que se cierre.",
  "text.lines_up_a_charge_you_can_see_on_the_ground_step_9fb66f": "Alinea un cargo que se puede ver en el suelo. Apártese, luego castigar.",
  "text.big_slow_and_tough_kite_it_while_you_deal_with_t_81c8c9": "Grande, lento y duro. Dilo mientras se ocupa del resto.",
  "text.its_fuse_ticks_faster_before_it_blows_back_off_o_69aede": "Su fusible se hace más rápido antes de que explote.",
  "text.splits_into_jellets_when_it_pops_area_damage_han_4e2406": "Se divide en Jellets cuando aparece. El daño del área maneja las sobras.",
  "text.small_jelly_pieces_weak_on_their_own_ea1dfc": "Pequeñas piezas de gelatina, mojadas por su cuenta.",
  "text.its_shield_soaks_hits_from_the_front_and_covers__241479": "Su escudo empapa golpes desde el frente y cubre a quien se esconde detrás de él. Se gira lentamente: redondea el lado.",
  "text.hangs_back_and_heals_everything_near_it_in_a_gre_b5a071": "Cuelga atrás y sana todo cerca de él en un pulso verde.",
  "text.crouches_then_hops_over_cover_onto_the_ring_it_m_8be58e": "Crouches, luego salta sobre la cubierta en el anillo que marca.",
  "text.lobs_shells_from_far_away_each_one_marks_a_red_c_0eed8b": "Langostas conchas de lejos. Cada una marca un círculo rojo antes de que aterrice.",
  "text.rare_and_shiny_runs_away_and_vanishes_after_a_fe_ee55d0": "Raro y brillante. Huye y desaparece después de unos segundos. ¡Atrápalo por un bote!",
  "text.a_pylon_that_keeps_hatching_swarmers_take_it_out_a463e8": "Un pylon que sigue trayendo Swarmers, llévalo temprano.",
  "text.rings_of_bullets_summons_and_a_jump_slam_you_can_d79675": "Anillos de balas, convocaciones y un golpe de salto que puedes ver venir.",
  "text.charges_three_times_in_a_row_then_spirals_watch__97dd83": "Carga tres veces seguidas, luego espirales. Mira las líneas de carga.",
  "text.flies_at_range_fires_fans_and_marks_ground_strik_849266": "Alimenta al alcance, dispara a los aficionados y marca huelgas terrestres. Sigue moviéndose entre las zonas rojas.",
  "text.circles_you_then_dives_along_the_orange_line_and_61bb99": "Te rodea, luego bucea a lo largo de la línea naranja, y sus amigos siguen en una columna. Salga de la línea.",
  "text.swims_under_the_sand_where_nothing_can_hit_it_wa_9f4658": "Swims debajo de la arena donde nada puede golpearlo: mira la aleta. Se estalla fuera del anillo rojo, luego se encuentra expuesto.",
  "text.rolls_in_wide_arcs_and_grows_as_it_rolls_it_can__5fcd18": "Rodea en arcos anchos y crece a medida que gira. Apenas puede girar, así que paso lateral; los grandes se rompen en las paredes y sobre ti.",
  "text.leaves_burning_puddles_behind_it_and_swells_up_t_07f5e8": "Deja quemar charcos detrás de ella y se hincha para derramar una grande. Matarlo antes de pintar el suelo.",
  "text.rewinds_its_path_lights_up_then_marches_straight_fa5ceb": "Rebobinados (su camino se ilumina), luego marcha directamente en fila con su equipo. Bajando, toma un daño adicional.",
  "text.keeps_its_distance_and_blows_a_cone_of_wind_that_1d3a90": "Mantiene su distancia y sopla un cono de viento que te mete alrededor. Sal del cono pálido o salpica a través.",
  "text.bright_meadow_ae520a": "Pradera Radiante",
