  "text.the_bounce_strikes_back_4fe069": "EL REBOTE GOLPEA DE NUEVO",
  "text.royal_quake_every_landing_sends_a_ring_23eb82": "TERREMOTO REAL: CADA ATERRIZAJE ENVÍA UN ANILLO",
  "text.ex_fury_b862b0": "EX FURIA",
  "text.rampage_rex_inferno_7ff304": "Rampage Rex: Inferno",
  "text.everything_burns_cc2a67": "TODO SE QUEMA",
  "text.inferno_fire_breath_already_a4afaa": "INFERNO: ALIENTO DE FUEGO YA",
  "text.meltdown_6f4c45": "FUSIÓN DEL NÚCLEO",
  "text.hive_queen_nightshade_64566b": "Hive Queen: Nightshade",
  "text.the_swarm_remembers_da1bcf": "EL ENJAMBRE RECUERDA",
  "text.nightshade_walls_and_hives_together_23fb15": "MANCHA DE NOCHE: PAREDES Y COLMENAS JUNTAS",
  "text.the_last_brood_d6aa69": "EL ÚLTIMO BRODO",
  "text.titan_goliath_5e28c8": "Titan Goliat",
  "text.the_mountain_that_woke_up_83ba91": "LA MONTAÑA QUE DESPERTÓ",
  "text.titan_armour_plate_8de89e": "Placa de armadura del titán",
  "text.titan_hand_core_7b1c24": "Núcleo de la mano del titán",
  "text.titan_eye_08de1f": "Ojo Titan",
  "text.once_tiny_garden_helpers_these_machines_now_mist_1558e4": "Una vez pequeños ayudantes del jardín, estas máquinas ahora se equivocan cada bota para una hierba.",
  "text.the_islands_oldest_delivery_bot_still_insists_th_70852e": "El bot de entrega más antiguo de las islas aún insiste en que cada paquete llegue personalmente.",
  "text.a_courier_with_no_address_left_to_deliver_to_its_14143a": "Un mensajero sin dirección a la que dejar. Su ruta termina donde quiera que estés de pie.",
  "text.a_retired_fireworks_launcher_still_rehearsing_fo_c984e2": "Un lanzador retirado de fuegos artificiales, todavía ensayando para un festival que nunca llegó.",
  "text.its_compass_broke_years_ago_it_has_been_checking_adba8f": "Su brújula rompió hace años, ha estado revisando todas las direcciones desde entonces.",
  "text.three_short_knocks_were_once_the_repair_crew_s_s_bcacff": "Tres golpes cortos fueron una vez el saludo secreto del equipo de reparación.",
  "text.the_watchtower_sentry_can_count_the_scratches_on_c73dcc": "El centinela de la torre puede contar los arañazos en su casco desde toda la isla.",
  "text.a_quarry_hauler_with_excellent_acceleration_and__1029b6": "Un transportador de canteras con excelente aceleración y absolutamente sin frenos.",
  "text.under_that_heavy_shell_is_a_remarkably_small_bat_5d4742": "Bajo esa cáscara pesada es una batería notablemente pequeña y un enorme sentido del deber.",
  "text.the_warning_sticker_fell_off_the_warning_noise_f_02ac0e": "El ruido de advertencia, por suerte, sigue funcionando.",
  "text.the_recycling_plant_called_this_self_repair_the__92b56d": "La planta de reciclaje llamó a este auto-reparador. El equipo de campo lo llama papeleo extra.",
  "text.a_little_piece_of_a_much_bigger_problem_determin_9984a9": "Un pequeño pedazo de un problema mucho más grande, decidido a hacer su propio camino.",
  "text.the_factory_foreman_never_received_the_shutdown__614054": "El capataz de fábrica nunca recibió la orden de cierre.",
  "text.built_to_shelter_workers_from_falling_rock_it_st_30a8cc": "Construido para proteger a los trabajadores de la caída de la roca; todavía pone a todos los demás primero.",
  "text.its_medical_license_expired_with_the_old_network_4e514c": "Su licencia médica caducó con la vieja red. Su manera de dormir sigue siendo entusiasta.",
  "text.the_island_drains_needed_a_maintenance_robot_tha_25ca9a": "Los desagües de la isla necesitaban un robot de mantenimiento que pudiera saltar. Nadie especificó un punto de aterrizaje.",
  "text.an_irrigation_system_that_found_the_wrong_kind_o_7b0a51": "Un sistema de riego que encontró el tipo equivocado de recipiente en el cobertizo de suministro.",
  "text.every_loose_bolt_on_the_islands_eventually_ends__83950b": "Cada Bolt suelto en las islas finalmente termina en los bolsillos de este coleccionista.",
  "text.the_first_bopper_promoted_itself_when_the_human__947489": "El primer Bopper se promovió cuando los supervisores humanos se fueron. Su corona es una antena.",
  "text.the_excavation_project_stopped_at_bedrock_rex_to_8bf630": "El proyecto de excavación se detuvo en la roca. Rex tomó eso personalmente.",
  "text.from_her_aerial_command_post_she_conducts_the_fa_f2d7d4": "Desde su puesto de mando aéreo, conduce la fábrica enjambre como una banda de latón.",
  "text.the_central_relay_has_waited_through_a_thousand__3619a8": "El relé central ha esperado a través de mil atardeceres tranquilos. Ahora cada isla está llamando inmediatamente.",
  "text.a_junior_supervisor_practising_a_royal_entrance__43e53e": "Un supervisor junior practicando una entrada real antes de la promoción real.",
  "text.a_prototype_digger_that_already_dreams_of_moving_bf3a30": "Un prototipo que ya sueña con mover montañas.",
  "text.her_first_command_assignment_is_this_island_she__03b2ed": "Su primera misión de mando es esta isla, tiene la intención de dar una buena impresión.",
  "text.a_portable_workshop_unfortunately_its_only_repai_004521": "Un taller portátil. Desafortunadamente, su único plan de reparación es construir más problemas.",
  "text.the_network_sends_this_collector_when_an_overdue_f55499": "La red envía a este coleccionista cuando un pedido de trabajo atrasado se convierte en una leyenda.",
  "text.the_newest_member_of_the_recovery_crew_brought_a_cc8b08": "El nuevo miembro del equipo de recuperación trajo un casco prestado y un mapa dibujado en crayon. Ambos han demostrado ser sorprendentemente fiables.",
  "text.a_rescue_worker_who_once_held_a_collapsing_bridg_44755c": "Un trabajador de rescate que una vez sostuvo un puente colapsante hasta que el último mensajero cruzó. La armadura pesada es principalmente para la paz mental de todos los demás.",
  "text.the_old_island_racing_champion_traded_prize_mone_a07a46": "El viejo campeón de carreras de la isla ha negociado dinero para un par de botas experimentales. Las marcas de scorch ahora son una firma registrada.",
  "text.a_radio_operator_who_can_hear_the_rhythm_hiding__b613cb": "Un operador de radio que puede escuchar el ritmo escondido en el chat de máquina. Cada toma es cronometrada al siguiente ritmo.",
  "text.enemy_92b09d": "ENEMIGO",
  "text.a_veteran_of_the_old_island_network_patched_up_a_9525a3": "Un veterano de la vieja red de la isla, parcheó y envió de vuelta a patrullar.",
  "text.keep_moving_and_watch_its_wind_up_e55101": "Sigan moviéndose y vean su viento hacia arriba.",
  "text.biome_05c008": "BIOMA",
