  "text.crackling_drones_chain_lightning_off_every_enemy_6754b6": "Los aviones no tripulados desencadenaron a todos los enemigos que hundieron, y los pernos de la tormenta saltan 2 veces más.",
  "text.napalm_rockets_8fdd8d": "Cohetes de napalm",
  "text.rockets_set_everything_ablaze_and_splash_burning_5976d9": "Los cohetes ponen todo ablaze y salpicaduras queman piscinas de napalm donde aterrizan. Su rastro aún se quema.",
  "text.ice_saws_8e4ea7": "Hielo Saws",
  "text.frozen_saw_blades_freeze_what_they_slice_shatter_1eb42a": "Las cuchillas de sierra congelados congelan lo que rebanan; los novas que rompen todavía pulsan alrededor tuyo.",
  "text.supernova_field_f4b2cc": "Campo de supernova",
