  "text.tesla_traps_c80060": "Tesla Traps",
  "text.mines_that_burst_into_chain_lightning_jumping_th_963fb4": "Minas que irrumpen en relámpagos de cadena, saltando a través de la multitud alrededor de cada explosión.",
