  "text.enemy_shots_travel_twice_as_fast_8e413e": "Los disparos enemigas viajan dos veces más rápido.",
  "text.level_up_5b0ee6": "¡SUBES DE NIVEL!",
  "text.pick_1_of_3_cards_click_or_keys_1_3_the_ribbon_a_c71357": "Elija 1 de 3 cartas (clic, o teclas 1-3). La cinta en la parte inferior dice lo que actualiza: LEFT CLICK, Right CLICK, SPECIAL, AUTO WEAPON o ITEM.",
  "text.evolution_fork_634218": "ELIGE TU EVOLUCIÓN",
  "text.enough_ranks_to_evolve_pick_one_of_the_two_forms_2fd106": "¡Suficientes rangos para evolucionar! Escoge una de las dos formas. Cada cambio de cómo funciona el artículo y añade una etiqueta que la nueva Mods puede pulsar.",
  "text.the_shop_37cbe7": "LA TIENDA",
  "text.mods_sit_in_5_slots_and_change_how_your_damage_w_71e69c": "Mods sentarse en 5 ranuras y cambiar cómo funciona el daño. Oro que mantiene gana interés en cada etapa clara, por lo que el ahorro puede pagar.",
  "text.mod_order_matters_7598df": "EL ORDEN DE LOS MODS IMPORTA",
  "text.damage_flows_through_your_mods_left_to_right_dam_1e221f": "El daño fluye a través de su Mods LEFT a la DERECCIÓN: (damage + adds) x mults. Mover plana \"+damage\" Mods antes de \"x damage\" con las flechas. Echo copia el Mod a su derecha.",
  "text.elite_07576c": "¡ELITE!",
  "text.a_big_tough_enemy_with_a_modifier_shield_fast_sp_891aa6": "Un enemigo grande y duro con un modificador (escudo, rápido, dividido...). Su barra de cráneo muestra su vida. Golpéalo por un cofre de tesoros.",
  "text.exposed_e6c328": "EXPUESTO",
  "text.right_click_hits_expose_enemies_30_damage_from_e_38bc87": "Golpes con el botón derecho Expose enemigos: +30% daño de todos por 4 s. Abrir con el clic derecho, terminar con la izquierda.",
  "text.burn_ticks_damage_shock_makes_enemies_take_20_fr_22dfd5": "Quemar garrapatas daño, Shock hace que los enemigos tomen +20%, Freeze los detiene. Ponga dos en el mismo enemigo para un combo.",
  "text.status_combo_f68922": "¡ESTATUS COMBO!",
  "text.burn_shock_overload_blast_kill_a_frozen_enemy_sh_c6ed94": "Burn + Shock = OVERLOAD blast. Kill a Frozen enemy = SHATTER. Una explosión en un enemigo ardiente = NAPALM. Mods puede hacer cada uno más fuerte.",
  "text.it_changes_its_attacks_at_66_and_33_life_red_zon_bf37e5": "Cambia de ataques al 66% y al 33% de vida. Las zonas y líneas rojas avisan del peligro: atraviésalas con un impulso (⟪0⟫) o desvía los disparos (⟪1⟫).",
  "text.treasure_chest_81663c": "COFRE DEL TESORO",
  "text.walk_into_it_for_a_free_item_on_the_spot_the_arr_3230d7": "Caminar en ella para un artículo libre en el lugar. La flecha en el borde de la pantalla apunta a la más cercana.",
  "text.special_ready_f6a478": "LISTO ESPECIAL",
  "text.press_or_middle_click_for_your_special_it_rechar_03aa5b": "Pulse ⟪0⟫ (o clic medio) para su especial. Se recarga con el tiempo.",
  "text.ultimate_ready_d08f2b": "ULTIMATE LISTO",
  "text.press_perfect_dodges_parries_and_kills_charge_yo_916d6b": "Pulse ⟪0⟫! Dodges perfectos, parries y matas cobran lo último de su héroe.",
  "text.style_meter_8e60e9": "MEDIDOR DE ESTILO",
  "text.fast_kills_perfect_dodges_and_parries_raise_your_9b344a": "Los asesinatos rápidos, los dodges perfectos y los parries levantan su estilo de D a SS. El estilo más alto da más puntaje y XP.",
  "text.gear_f7f969": "ENGRANAJE",
  "text.each_gear_rerolls_one_set_of_level_up_cards_on_t_5e783d": "Cada equipo rerolla un conjunto de tarjetas de nivel-up (⟪0⟫ en la pantalla de nivel-up).",
  "text.stage_clear_4e29fa": "FASE SUPERADA",
  "text.walk_into_the_portal_for_the_next_stage_every_st_adf1cd": "Entra en el portal para pasar a la siguiente fase. Cada fase es más difícil y cada 4.ª termina con el jefe final.",
  "text.a_teammate_revives_you_by_standing_next_to_you_f_b91da8": "Un compañero de equipo le revive al estar a su lado durante 3 s. Haga clic para ver a otro compañero de equipo mientras tanto.",
  "text.teammate_down_47afc6": "COMPAÑERO CAÍDO",
  "text.stand_next_to_them_for_3_s_to_revive_them_you_bo_80d4d7": "Pónganse a su lado por 3 s para revivirlos. Ambos tienen un momento de invencibilidad.",
  "text.walk_around_with_or_the_left_stick_you_always_fa_4087eb": "Camina alrededor con ⟪0⟫ ⟪1⟫ ⟪2⟫ ⟪3⟫ o el palo izquierdo. Siempre te enfrentas a donde apuntas.",
  "text.aim_and_fire_e2180c": "APUNTE Y FUEGO",
  "text.aim_with_the_mouse_or_right_stick_and_hold_left__395851": "Apunta con el ratón o el stick derecho y mantén el CLIC IZQUIERDO para disparar ⟪0⟫. Destruye los ⟪1⟫ bots de práctica.",
  "text.hold_right_click_or_x_for_your_its_hits_expose_e_c35ec0": "Sostenga la CLICK DERECHO (o X) para su ⟪0⟫. Sus golpes EXPOSE enemigos: +30% daño de todos por 4 s. Exponga el gran bot.",
  "text.press_to_dash_you_can_t_be_hit_mid_dash_dash_thr_ff9c38": "Presione ⟪0⟫ para deshacerse: no se puede golpear a media hora. Dash TROUGH un tiro rosa justo antes de que te golpee.",
  "text.press_or_b_right_as_a_pink_shot_reaches_you_to_p_99aaf3": "Presione ⟪0⟫ (o B) justo cuando un tiro rosa le llega a PARRY de nuevo en el tirador.",
  "text.your_special_is_ready_press_or_rb_to_set_off_you_fa2e3b": "Su especial está listo: presione ⟪0⟫ (o RB) para apagar sus ⟪1⟫ junto a los bots. Se recarga con el tiempo.",
  "text.ultimate_df1d2d": "DEFINITIVA",
  "text.perfect_dodges_parries_and_kills_charge_your_her_5caa68": "Dodges perfectos, parries y matas cobran el ULTIMATE de tu héroe. Está lleno: presion ⟪0⟫ (o R3).",
  "text.level_up_529820": "NIVEL ARRIBA",
  "text.kills_drop_xp_gems_that_fly_to_you_a_full_xp_bar_8d848d": "Mata las gemas de gota XP que vuelan a usted. Una barra XP completa es un nivel-up: recoger UNA de las 3 tarjetas. La cinta dice lo que actualiza.",
  "text.chests_pop_up_on_the_map_every_30_s_the_arrow_at_2bf388": "Los pechos aparecen en el mapa cada 30 s (la flecha en el borde de la pantalla apunta a ellos). Camine hacia éste para un artículo libre.",
